import requests

task_id = "task-a9fdfc15"

# Request a demo to understand the task
params = {
    'task_id': task_id,
    'action': 'request_demos'
}
# Try different paths
for path in ['/api/task', '/api/v1/task', '/arc/api', '/api/task/demo']:
    try:
        response = requests.post(f'http://localhost:8000{path}', json=params, timeout=1)
        if response.status_code == 200 or response.status_code == 500:
            print(f"Path {path}: {response.text[:200]}")
            break
    except:
        pass
